import React, { useEffect, useState } from "react";
import axios from "axios";

const API_KEY = "dict.1.1.20261026T133750Z.37296408abab3f14.7def49b454592fccccd0a376cb10f45ec5ddcadf";

export default function Translate({ text }) {
  const [translated, setTranslated] = useState("");

  useEffect(() => {
    const word = (text || "").trim();

    setTranslated("");

    if (!word) {
      return;
    }

    const cancelToken = axios.CancelToken.source();
    let active = true;

    // Ждём паузу в наборе, чтобы не отправлять запрос на каждую букву.
    const timer = setTimeout(async () => {
      try {
        const { data } = await axios.get(
          "https://dictionary.yandex.net/api/v1/dicservice.json/lookup",
          {
            params: {
              key: API_KEY,
              lang: "ru-en",
              text: word
            },
            cancelToken: cancelToken.token
          }
        );

        if (!active) {
          return;
        }

        const firstDefinition = data.def && data.def[0];
        const firstTranslation =
          firstDefinition &&
          firstDefinition.tr &&
          firstDefinition.tr[0];

        setTranslated(
          firstTranslation ? firstTranslation.text : "Перевод не найден"
        );
      } catch (error) {
        if (!active || axios.isCancel(error)) {
          return;
        }

        setTranslated("Ошибка перевода. Проверь ключ и соединение.");
      }
    }, 400);

    return () => {
      active = false;
      clearTimeout(timer);
      cancelToken.cancel();
    };
  }, [text]);

  return (
    <div>
      <h1 className="title">{translated}</h1>
    </div>
  );
}